<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Orden de Compra OC-0124-001 – CMAN Global Construction</title>
  <link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800&family=Open+Sans:wght@400;600&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --gold: #E8A020;
      --dark-gold: #C8870A;
      --blue-dark: #1A3A5C;
      --blue-mid: #2563A8;
      --gray-dark: #4a4a4a;
      --text: #222;
      --mid-gray: #ddd;
      --row-alt: #fafafa;
    }

    body {
      font-family: 'Open Sans', sans-serif;
      background: #c8c8c8;
      color: var(--text);
      font-size: 12px;
      margin: 0;
      padding: 20px 0;
    }

    /* === CARTA PAGE === */
    .page {
      position: relative;
      width: 816px;       /* Letter: 8.5in @ 96dpi */
      min-height: 1056px; /* Letter: 11in @ 96dpi */
      margin: 0 auto 30px;
      background: #fff;
      box-shadow: 0 4px 32px rgba(0,0,0,0.22);
      overflow: hidden;
    }

    /* Background image (the H.jpg letterhead) */
    .page-bg {
      position: absolute;
        top: 0;
        left: 0;
        width: 816px;
        height: 1056px;
    }

    /* All content sits above background */
    .page-content {
      position: relative;
      z-index: 1;
      /* Top padding = height of header strip in H.jpg (~100px) */
      /* Bottom padding = height of footer strip (~80px) */
      padding: 108px 36px 95px 36px;
    }

    /* ── ORDEN TITLE ── */
    .doc-title {
      text-align: center;
      margin-bottom: 6px;
    }
    .doc-title h1 {
      font-family: 'Montserrat', sans-serif;
      font-size: 20px;
      font-weight: 800;
      color: var(--gray-dark);
      letter-spacing: 3px;
      text-transform: uppercase;
    }
    .doc-title .form-code {
      font-size: 9px;
      color: #999;
      letter-spacing: 1px;
      margin-top: 2px;
    }

    /* ── TOP META ── */
    .top-section {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      margin: 10px 0 6px;
    }
    .company-name {
      font-family: 'Montserrat', sans-serif;
      font-size: 12px;
      font-weight: 800;
      color: var(--blue-mid);
      text-transform: uppercase;
    }
    .company-details {
      font-size: 9.5px;
      color: #444;
      line-height: 1.65;
      margin-top: 2px;
    }
    .rfc-tag { font-weight: 700; color: var(--blue-mid); }
    .meta-box { text-align: right; }
    .meta-row { font-size: 10px; margin-bottom: 2px; }
    .meta-label { color: #555; }
    .meta-value { font-weight: 700; }
    .oc-number { color: #e03030; font-weight: 800; }

    /* divider */
    .divider {
      height: 2px;
      background: linear-gradient(90deg, var(--gold), var(--gray-dark));
      margin: 6px 0;
    }

    /* ── PARTIES TABLE ── */
    .parties-table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 0;
    }
    .parties-table th {
      background: var(--gold);
      color: #fff;
      font-family: 'Montserrat', sans-serif;
      font-weight: 700;
      font-size: 10px;
      letter-spacing: 1px;
      text-transform: uppercase;
      padding: 5px 14px;
      text-align: left;
      width: 50%;
    }
    .parties-table td {
      vertical-align: top;
      padding: 8px 14px;
      font-size: 10px;
      line-height: 1.65;
      border-right: 1px solid var(--mid-gray);
      border-bottom: 1px solid var(--mid-gray);
    }
    .party-name { font-weight: 700; font-size: 11px; margin-bottom: 1px; }

    .delivery-note {
      background: rgba(248,243,230,0.85);
      text-align: center;
      font-style: italic;
      font-size: 9.5px;
      color: #666;
      padding: 5px 14px;
      border-bottom: 1px solid var(--mid-gray);
    }

    /* ── ITEMS TABLE ── */
    .items-table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 0;
    }
    .items-table thead tr th {
      background: var(--gold);
      color: #fff;
      font-family: 'Montserrat', sans-serif;
      font-weight: 700;
      font-size: 9.5px;
      letter-spacing: 0.5px;
      text-transform: uppercase;
      padding: 6px 8px;
      text-align: center;
      border: 1px solid var(--dark-gold);
    }
    .items-table thead tr th:nth-child(3) { text-align: left; }
    .items-table tbody tr td {
      padding: 5px 8px;
      border: 1px solid var(--mid-gray);
      text-align: center;
      font-size: 10px;
      vertical-align: middle;
      background: rgba(255,255,255,0.88);
    }
    .items-table tbody tr:nth-child(even) td { background: rgba(250,250,250,0.88); }
    .items-table tbody tr:hover td { background: rgba(255,248,236,0.95); }
    .items-table tbody tr td.desc { text-align: left; }
    .code-link { color: var(--blue-mid); font-weight: 600; font-size: 9.5px; }
    .total-cell { font-weight: 700; }
    .items-table tbody tr.empty-row td {
      height: 20px;
      background: rgba(255,255,255,0.7);
    }

    /* ── FOOTER AREA ── */
    .footer-area {
      display: flex;
      gap: 20px;
      margin-top: 10px;
    }
    .comments-block { flex: 1; }
    .comments-label {
      font-family: 'Montserrat', sans-serif;
      font-weight: 700;
      font-size: 9.5px;
      color: var(--blue-mid);
      text-transform: uppercase;
      margin-bottom: 4px;
    }
    .comments-area {
      border: 1px solid var(--mid-gray);
      min-height: 60px;
      background: rgba(250,250,250,0.8);
    }

    .totals-block { min-width: 220px; }
    .totals-row {
      display: flex;
      justify-content: space-between;
      padding: 3px 8px;
      font-size: 10.5px;
      color: #444;
      background: rgba(255,255,255,0.85);
    }
    .totals-row:nth-child(odd) { background: rgba(250,250,250,0.85); }
    .totals-row .t-label { font-weight: 600; }
    .totals-row .t-value { font-weight: 600; }
    .totals-row.grand-total {
      background: var(--gray-dark);
      color: #fff;
      font-family: 'Montserrat', sans-serif;
      font-weight: 800;
      font-size: 12px;
      padding: 5px 8px;
      margin-top: 2px;
    }

    .contact-bar {
      margin-top: 10px;
      background: rgba(240,240,240,0.85);
      padding: 5px 14px;
      font-size: 9px;
      color: #555;
      text-align: center;
      font-style: italic;
    }

    @media print {
      body { background: #fff; padding: 0; }
      .page { box-shadow: none; margin: 0; }
      @page { size: letter; margin: 0; }
    }
  </style>
</head>
